function applyEvent(view, event) {
  switch (event.type) {
    case 'work.add': {
      const item = event.payload;
      if (item && typeof item === 'object' && typeof item.id === 'string') {
        const normalized = { ...item };
        if (normalized.tier !== undefined) {
          if (normalized.size === undefined) {
            normalized.size = normalized.tier;
          }
          delete normalized.tier;
        }
        if (normalized.rigor === undefined && normalized.risk === 'heavy') {
          normalized.rigor = 'high';
        }
        foldLegacyStage(normalized);
        if (normalized.workflowStep !== undefined) {
          normalized.workflowStep = canonicalStep(normalized, normalized.workflowStep);
        }
        view.work[item.id] = { ...DEFAULTS, ...normalized };
      }
      break;
    }
    case 'work.move': {
      const { id, from, to, ask, answer, role, learning, headAtTake, headAtReturn, branchHeadAtTake, branchHeadAtReturn, mergedSha, mergedInto, reason, parentSnapshotAtAsk, claimTrigger, statusAtAsk, durableStatusAtAsk, writer, statusCategory, parkReason, rationale, alternatives, source, askSource, approved } = event.payload ?? {};
